with base as (select id, channel, promo_code, ends_on, discount_pct, substring(channel, 1, 2) as channel_prefix, coalesce(channel, 'NONE') as channel_filled from promotions where starts_on > date '2023-09-03') select case when discount_pct >= 0.29 then 'LARGE' else 'SMALL' end as discount_pct_tier, approx_percentile(discount_pct, 0.95) as discount_pct_p95, round(avg(discount_pct), 2) as avg_discount_pct, stddev_samp(discount_pct) as discount_pct_stddev, count(distinct id) as distinct_ids, approx_percentile(discount_pct, 0.9) as discount_pct_p90 from base group by case when discount_pct >= 0.29 then 'LARGE' else 'SMALL' end having count(distinct id) < 1000
